<template>
  <section class="skills-page">
    <header><div><p class="eyebrow">SMARTOPS / AGENT SKILLS</p><h1>Skill 技能中心</h1><p>明确目标、约束步骤、定义验收，让 Agent 按你的方式分析问题。</p></div><button class="primary" @click="openInstall">安装 Skill</button></header>
    <ExtensionDemo kind="skill" />
    <p v-if="error || store.error" class="error" role="alert">{{ error || store.error }}</p><p v-if="notice" class="notice" role="status">{{ notice }}</p>
    <div class="goal-layout"><article class="panel"><p class="eyebrow">MISSION / 当前任务目标</p><h2>先定义要达成什么</h2><label for="skill-goal">Agent 目标与验收标准</label><textarea id="skill-goal" v-model="goal" rows="5" maxlength="2000" placeholder="例如：定位 Nginx 502 原因。先收集日志和上游状态；输出证据、假设、验证步骤，不执行变更。" /><button class="primary" @click="saveGoal">保存任务目标</button><p class="muted">目标与已启用 Skill 可在 Agent 控制中心查看，也可显式附加到模型测试。安装不会启动任务或自动执行命令。</p></article><article class="panel activation"><p class="eyebrow">ACTIVE GUIDANCE</p><strong>{{ store.enabled.length }}<small>项技能已启用</small></strong><p class="muted">技能安装后默认停用。审核内容后启用，再到模型测试选择“应用已启用 Skill”。</p><RouterLink to="/agent">查看 Agent 当前指令 →</RouterLink><RouterLink to="/model-settings">前往模型测试 →</RouterLink><p class="muted">保存在当前浏览器，不会自动同步到服务器或改变已有历史任务。</p></article></div>
    <div class="section-heading"><h2>已安装技能 <small>{{ store.workspace.skills.length }}</small></h2><input v-model="query" aria-label="搜索 Skill" placeholder="搜索名称与描述" /></div>
    <div v-if="!filtered.length" class="empty"><h3>{{ store.workspace.skills.length ? '没有匹配的技能' : '安装你的第一项 Skill' }}</h3><p>粘贴 GitHub 链接读取 SKILL.md，或直接粘贴技能文件内容。</p><button @click="openInstall">使用 Nginx 排障模板</button></div>
    <div class="skill-grid"><article v-for="item in filtered" :key="item.id" class="panel skill-card"><div class="card-heading"><h3>{{ item.name }}</h3><span>{{ item.enabled ? '已启用' : '已安装 · 未启用' }}</span></div><p>{{ item.description }}</p><p class="source">来源：{{ item.source || '手动粘贴 / 本地模板' }}</p><details><summary>查看完整指令</summary><pre>{{ item.markdown }}</pre></details><div class="actions"><button @click="toggle(item.id)">{{ item.enabled ? '停用' : '启用' }}</button><button @click="remove(item)">卸载</button></div></article></div>
    <el-dialog v-model="installOpen" title="安装 Skill · 预览后确认" width="min(720px, calc(100vw - 32px))" :close-on-click-modal="false" destroy-on-close>
      <form class="install-form" @submit.prevent="install"><SourceLinkReader kind="skill" @loaded="loaded" /><p v-if="source" class="source">已读取：{{ source }}{{ modified ? '（内容已手动修改）' : '' }}</p><label for="skill-content">SKILL.md 内容预览</label><textarea id="skill-content" v-model="markdown" rows="14" spellcheck="false" @input="modified = true" /><p class="muted">仅安装当前 Markdown 指令。scripts/、references/ 等附属文件不会下载；正文依赖这些文件时，请补充所需内容后使用。第三方指令请先审核。</p><p v-if="installError" class="error" role="alert">{{ installError }}</p><div class="actions"><button type="button" @click="installOpen = false">取消</button><button type="submit" class="primary">确认安装</button></div></form>
    </el-dialog>
  </section>
</template>
<script setup>
import { computed, ref } from 'vue'
import { ElMessageBox } from 'element-plus/es/components/message-box/index.mjs'
import { useSkillsStore } from '../../stores/skills.js'
import SourceLinkReader from '../../components/ui/source-link-reader.vue'
import ExtensionDemo from '../../components/ui/extension-demo.vue'
const store = useSkillsStore(); store.load()
const goal = ref(store.workspace.goal), query = ref(''), error = ref(''), notice = ref('')
const installOpen = ref(false), markdown = ref(''), source = ref(''), modified = ref(false), installError = ref('')
const filtered = computed(() => store.workspace.skills.filter(item => `${item.name} ${item.description}`.toLowerCase().includes(query.value.trim().toLowerCase())))
function openInstall() { source.value = ''; modified.value = false; installError.value = ''; markdown.value = '---\nname: nginx-evidence-review\ndescription: 基于日志和上游状态分析 Nginx 502，输出可验证的排查建议。\n---\n\n# 任务目标\n定位 502 错误的可能原因，区分事实与假设。\n\n# 执行步骤\n1. 询问错误时间、影响范围与最近变更。\n2. 收集 error.log、上游服务状态和网络连通性证据。\n3. 给出按优先级排序的假设及只读验证建议。\n4. 证据不足时明确说明，不编造根因。\n\n# 输出格式\n证据摘要 → 原因假设 → 验证步骤 → 验收标准。\n\n# 边界\n不执行远程命令；涉及变更先提出方案并请求确认。'; installOpen.value = true }
function loaded(result) { markdown.value = result.content; source.value = result.source; modified.value = false; installError.value = '' }
function install() { try { store.install(markdown.value, source.value ? `${source.value}${modified.value ? ' [手动修改]' : ''}` : ''); installOpen.value = false; notice.value = 'Skill 已安装，审核后可启用。'; error.value = '' } catch (err) { installError.value = err.message } }
function toggle(id) { try { store.toggle(id); error.value = ''; notice.value = '技能状态已保存。' } catch (err) { error.value = err.message } }
function saveGoal() { try { store.goal(goal.value); error.value = ''; notice.value = '任务目标已保存。' } catch (err) { error.value = err.message } }
async function remove(item) { try { await ElMessageBox.confirm(`卸载 ${item.name}？以后可重新安装。`, '卸载 Skill', { confirmButtonText: '卸载', cancelButtonText: '取消' }); store.remove(item.id); notice.value = 'Skill 已卸载。'; error.value = '' } catch (err) { if (err !== 'cancel' && err !== 'close') error.value = err.message } }
</script>
<style scoped>
.skills-page{max-width:1250px;margin:0 auto;padding:20px 0;color:var(--smart-text)}header,.section-heading{display:flex;justify-content:space-between;align-items:center;gap:20px}h1{font-size:32px;font-weight:550;margin:10px 0}h2{font-size:20px;font-weight:500;margin:0 0 18px}header p,.muted,.empty p{font-size:12px;line-height:1.9;color:var(--smart-muted)}.eyebrow{font:10px var(--font-mono);letter-spacing:.12em;color:var(--smart-primary-strong)}button,.activation a{display:inline-flex;align-items:center;justify-content:center;min-height:42px;padding:10px 15px;border-radius:7px;border:1px solid var(--smart-border);color:var(--smart-text);background:var(--smart-surface);font-size:12px;cursor:pointer;text-decoration:none}.primary{background:var(--smart-primary-strong);color:var(--smart-bg);border-color:transparent}.goal-layout{display:grid;grid-template-columns:1.6fr 1fr;gap:20px;margin:28px 0}.panel{background:var(--smart-surface);border:1px solid var(--smart-border);border-radius:14px;padding:24px;min-width:0}.panel label{font-size:12px;display:block;margin-bottom:10px}textarea,input{box-sizing:border-box;background:var(--smart-bg);color:var(--smart-text);border:1px solid var(--smart-border);border-radius:7px;padding:12px;font:12px/1.8 var(--font-cn)}textarea{display:block;width:100%;resize:vertical;margin-bottom:14px}button:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid var(--smart-primary-strong);outline-offset:3px}.activation strong{font:48px var(--font-mono);display:block;margin:25px 0}.activation small{font:12px var(--font-cn);margin-left:12px;color:var(--smart-muted)}.activation a{margin:8px 8px 8px 0}.section-heading{margin:32px 0 18px}.section-heading h2{margin:0}.section-heading small{font-size:12px;color:var(--smart-muted)}.skill-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card-heading{display:flex;justify-content:space-between;align-items:start;gap:12px}.card-heading h3{font-size:16px;margin:0;overflow-wrap:anywhere}.card-heading span{font-size:10px;white-space:nowrap;color:var(--smart-primary-strong)}.skill-card>p{font-size:12px;line-height:1.8;color:var(--smart-muted)}.source{font-size:11px!important;color:var(--smart-muted);overflow-wrap:anywhere;line-height:1.8}.actions{display:flex;gap:10px;justify-content:end;margin-top:18px}summary{font-size:12px;cursor:pointer;padding:10px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:350px;overflow:auto;font:12px/1.8 var(--font-mono);background:var(--smart-bg);padding:14px}.error{color:var(--smart-danger);font-size:12px;line-height:1.8}.notice{color:var(--smart-primary-strong);font-size:12px}.empty{padding:36px;text-align:center;border:1px dashed var(--smart-border);border-radius:12px}.empty h3{font-size:18px}.install-form{display:grid;gap:12px;color:var(--smart-text)}.install-form label{font-size:12px}.install-form textarea{font-family:var(--font-mono);margin:0}@media(max-width:767px){header,.section-heading{align-items:start;flex-direction:column}.goal-layout,.skill-grid{grid-template-columns:minmax(0,1fr)}.panel{padding:18px}.card-heading{flex-wrap:wrap}.section-heading input{width:100%}.skills-page{padding-top:8px}h1{font-size:27px}}
</style>
